import { X } from 'lucide-react';
import type { HTMLAttributes, ReactNode, Ref } from 'react';
import { useI18n } from '../../i18n/I18nProvider';
import { cn } from '../../utils/cn';
import { badgeVariants, type BadgeVariantProps } from './badge.variants';

export interface BadgeProps extends Omit<HTMLAttributes<HTMLSpanElement>, 'className'>, BadgeVariantProps {
  className?: string;
  ref?: Ref<HTMLSpanElement>;
  /** Leading dot in the tone colour (inherits the text colour on `solid`). */
  dot?: boolean;
  /** Renders a remove button; called on click, Enter or Space. */
  onRemove?: () => void;
  /** Accessible name of the remove button. Defaults to "Remove <label>" for string children. */
  removeLabel?: string;
  children?: ReactNode;
}

/** Compact label for status, counts and categories. Optionally removable (tags). */
export function Badge({
  tone,
  variant,
  size,
  shape,
  dot = false,
  onRemove,
  removeLabel,
  className,
  children,
  ...props
}: BadgeProps) {
  const { t } = useI18n();
  const s = badgeVariants({ tone, variant, size, shape });
  const label =
    removeLabel ?? (typeof children === 'string' ? t('common.removeItem', { label: children }) : t('common.remove'));
  return (
    <span className={cn(s.root(), onRemove && 'pe-1.5', className)} {...props}>
      {dot && <span aria-hidden className={s.dot()} />}
      {children}
      {onRemove && (
        <button type="button" aria-label={label} onClick={onRemove} className={s.remove()}>
          <X size={11} strokeWidth={2.4} aria-hidden />
        </button>
      )}
    </span>
  );
}

import { tv, type VariantProps } from '../../utils/tv';

/**
 * Tone × variant matrix. Text on a tinted surface uses the contrast-safe `*-text` aliases;
 * info and the category tones have no text alias, so they pair `text-foreground` with a
 * coloured dot instead of colouring the text itself.
 */
export const badgeVariants = tv({
  slots: {
    root: 'inline-flex max-w-full shrink-0 items-center gap-1.5 font-semibold whitespace-nowrap select-none',
    dot: 'size-1.5 shrink-0 rounded-full',
    remove: [
      '-me-1 grid size-4 shrink-0 cursor-interactive place-items-center rounded text-current opacity-70 transition-colors motion-reduce:transition-none',
      'hover:bg-foreground/10 hover:opacity-100',
      'focus-visible:opacity-100 focus-visible:outline-2 focus-visible:outline-offset-1 focus-visible:outline-focus-ring',
    ],
  },
  variants: {
    tone: {
      neutral: { dot: 'bg-muted-foreground' },
      primary: { dot: 'bg-primary' },
      success: { dot: 'bg-success' },
      warning: { dot: 'bg-warning' },
      destructive: { dot: 'bg-destructive' },
      info: { dot: 'bg-info' },
      violet: { dot: 'bg-category-violet' },
      cyan: { dot: 'bg-category-cyan' },
      amber: { dot: 'bg-category-amber' },
      rose: { dot: 'bg-category-rose' },
    },
    variant: {
      soft: {},
      outline: { root: 'border bg-transparent' },
      solid: { dot: 'bg-current' },
    },
    size: {
      /** Follows `data-density` (comfortable = md). */
      auto: { root: 'h-chip px-2.5 font-mono text-[10.5px]' },
      sm: { root: 'h-5 px-2 font-mono text-[10px]' },
      md: { root: 'h-[22px] px-2.5 font-mono text-[10.5px]' },
      lg: { root: 'h-6 px-2.5 text-[11.5px]' },
    },
    shape: {
      rounded: { root: 'rounded-md' },
      pill: { root: 'rounded-full' },
    },
  },
  compoundVariants: [
    // soft
    { variant: 'soft', tone: 'neutral', class: { root: 'bg-muted-foreground/16 text-foreground' } },
    { variant: 'soft', tone: 'primary', class: { root: 'bg-primary/14 text-primary-chip-text' } },
    { variant: 'soft', tone: 'success', class: { root: 'bg-success/15 text-success-chip-text' } },
    { variant: 'soft', tone: 'warning', class: { root: 'bg-warning/16 text-warning-chip-text' } },
    { variant: 'soft', tone: 'destructive', class: { root: 'bg-destructive/15 text-destructive-chip-text' } },
    { variant: 'soft', tone: 'info', class: { root: 'bg-info/15 text-foreground' } },
    { variant: 'soft', tone: 'violet', class: { root: 'bg-category-violet/18 text-foreground' } },
    { variant: 'soft', tone: 'cyan', class: { root: 'bg-category-cyan/18 text-foreground' } },
    { variant: 'soft', tone: 'amber', class: { root: 'bg-category-amber/20 text-foreground' } },
    { variant: 'soft', tone: 'rose', class: { root: 'bg-category-rose/18 text-foreground' } },
    // outline
    { variant: 'outline', tone: 'neutral', class: { root: 'border-border text-muted-foreground' } },
    { variant: 'outline', tone: 'primary', class: { root: 'border-primary/45 text-primary-text' } },
    { variant: 'outline', tone: 'success', class: { root: 'border-success/45 text-success-text' } },
    { variant: 'outline', tone: 'warning', class: { root: 'border-warning/50 text-warning-text' } },
    { variant: 'outline', tone: 'destructive', class: { root: 'border-destructive/45 text-destructive-text' } },
    { variant: 'outline', tone: 'info', class: { root: 'border-info/45 text-foreground' } },
    { variant: 'outline', tone: 'violet', class: { root: 'border-category-violet/45 text-foreground' } },
    { variant: 'outline', tone: 'cyan', class: { root: 'border-category-cyan/45 text-foreground' } },
    { variant: 'outline', tone: 'amber', class: { root: 'border-category-amber/50 text-foreground' } },
    { variant: 'outline', tone: 'rose', class: { root: 'border-category-rose/45 text-foreground' } },
    // solid — tone fill with its paired foreground. Category tones have no paired
    // foreground that holds contrast in every theme, so solid = a stronger tint.
    { variant: 'solid', tone: 'neutral', class: { root: 'bg-foreground text-background' } },
    { variant: 'solid', tone: 'primary', class: { root: 'bg-primary text-primary-foreground' } },
    { variant: 'solid', tone: 'success', class: { root: 'bg-success text-primary-foreground' } },
    { variant: 'solid', tone: 'warning', class: { root: 'bg-warning text-primary-foreground' } },
    { variant: 'solid', tone: 'destructive', class: { root: 'bg-destructive text-destructive-foreground' } },
    { variant: 'solid', tone: 'info', class: { root: 'bg-info text-background' } },
    {
      variant: 'solid',
      tone: 'violet',
      class: { root: 'bg-category-violet/30 text-foreground', dot: 'bg-category-violet' },
    },
    { variant: 'solid', tone: 'cyan', class: { root: 'bg-category-cyan/30 text-foreground', dot: 'bg-category-cyan' } },
    {
      variant: 'solid',
      tone: 'amber',
      class: { root: 'bg-category-amber/32 text-foreground', dot: 'bg-category-amber' },
    },
    { variant: 'solid', tone: 'rose', class: { root: 'bg-category-rose/30 text-foreground', dot: 'bg-category-rose' } },
  ],
  defaultVariants: { tone: 'neutral', variant: 'soft', size: 'auto', shape: 'rounded' },
});

export type BadgeVariantProps = VariantProps<typeof badgeVariants>;
export type BadgeTone = NonNullable<BadgeVariantProps['tone']>;

export { Badge, type BadgeProps } from './Badge';
export { badgeVariants, type BadgeVariantProps, type BadgeTone } from './badge.variants';
export { doc as badgeDoc } from './Badge.doc';

import { DirectionProvider } from '@base-ui/react/direction-provider';
import { createContext, useContext, useEffect, useMemo, useRef, type ReactNode } from 'react';
import { createFormatters, localeDirection, type I18nFormatters } from './format';
import { isValidTimeZone } from './time-zone';
import { catalogs } from './messages';
import { en, type Messages } from './messages/en';

export type Direction = 'ltr' | 'rtl';

/** What useI18n() returns: the translator, Intl formatters, the locale and the text direction. */
export interface I18n extends I18nFormatters {
  locale: string;
  dir: Direction;
  timeZone: string;
}

export interface I18nProviderProps {
  /** BCP 47 locale ("es", "es-MX", "ar"). Picks the built-in catalog by language; unknown → English. */
  locale: string;
  /** Overrides or additions on top of the built-in catalog (e.g. a full catalog for another language). */
  messages?: Partial<Messages>;
  /** Display time zone: system (default), UTC or an IANA name. Use the same zone on server and client. */
  timeZone?: string;
  /** Text direction; defaults to the locale's (rtl for Arabic, Hebrew, Persian, Urdu…). */
  dir?: Direction;
  /**
   * Where `dir` and `lang` are applied: `wrapper` (default) renders a `display: contents` div;
   * `document` sets them on `<html>` (also covers portalled overlays); `none` leaves it to you.
   */
  applyTo?: 'wrapper' | 'document' | 'none';
  children?: ReactNode;
}

const I18nContext = createContext<I18n | null>(null);
const DEFAULT_I18N: I18n = { locale: 'en', dir: 'ltr', timeZone: 'system', ...createFormatters('en', en) };

/** The built-in catalog for a locale's language, falling back to English. */
export function builtInMessages(locale: string): Messages {
  const lang = locale.split(/[-_]/)[0]?.toLowerCase() ?? '';
  return (catalogs as Record<string, Messages | undefined>)[lang] ?? en;
}

/**
 * Locale, messages and direction for every kit component below it. Also sets Base UI's
 * direction, so arrow-key navigation (Tabs, Menu, Slider, Toolbar…) follows RTL.
 */
export function I18nProvider({
  locale,
  messages,
  dir,
  timeZone = 'system',
  applyTo = 'wrapper',
  children,
}: I18nProviderProps) {
  const zone = isValidTimeZone(timeZone) ? timeZone : 'system';
  const warned = useRef<string | null>(null);
  useEffect(() => {
    if (process.env.NODE_ENV !== 'production' && zone !== timeZone && warned.current !== timeZone) {
      warned.current = timeZone;
      console.warn(`I18nProvider: invalid time zone "${timeZone}"; using system.`);
    }
  }, [zone, timeZone]);
  const direction = dir ?? localeDirection(locale);
  const value = useMemo<I18n>(() => {
    const merged: Messages = { ...builtInMessages(locale), ...messages };
    return { locale, dir: direction, timeZone: zone, ...createFormatters(locale, merged, zone) };
  }, [locale, messages, direction, zone]);

  useEffect(() => {
    if (applyTo !== 'document') return;
    const html = document.documentElement;
    const prev = { dir: html.getAttribute('dir'), lang: html.getAttribute('lang') };
    html.setAttribute('dir', direction);
    html.setAttribute('lang', locale);
    return () => {
      if (prev.dir === null) html.removeAttribute('dir');
      else html.setAttribute('dir', prev.dir);
      if (prev.lang === null) html.removeAttribute('lang');
      else html.setAttribute('lang', prev.lang);
    };
  }, [applyTo, direction, locale]);

  const content = <DirectionProvider direction={direction}>{children}</DirectionProvider>;
  return (
    <I18nContext.Provider value={value}>
      {applyTo === 'wrapper' ? (
        <div dir={direction} lang={locale} className="contents">
          {content}
        </div>
      ) : (
        content
      )}
    </I18nContext.Provider>
  );
}

/** Translator, Intl formatters, locale and direction. Outside an I18nProvider: English, LTR. */
export function useI18n(): I18n {
  return useContext(I18nContext) ?? DEFAULT_I18N;
}

/** The provider's value, or null outside one (lets components keep runtime-locale defaults). */
export function useOptionalI18n(): I18n | null {
  return useContext(I18nContext);
}

/**
 * `dir` for portalled overlays: rendered outside the provider's wrapper, they carry the
 * direction themselves. Undefined outside a provider, so the document's direction applies.
 */
export function usePortalDir(): Direction | undefined {
  return useContext(I18nContext)?.dir;
}

import type { MessageKey, Messages } from './messages/en';

/** Values interpolated into a message: `{name}` placeholders and plural selectors. */
export type MessageVars = Record<string, string | number>;

/** Options for locale-aware byte or bit sizes. */
export interface FormatBytesOptions {
  /** BCP 47 locale; defaults to English. */
  locale?: string;
  /** Decimal SI (default) or binary IEC multiples. Bits always use 1000. */
  base?: 1000 | 1024;
  /** The input's unit; defaults to bytes. */
  unit?: 'byte' | 'bit';
  /** Intl label width; binary multiples always use IEC symbols. Defaults to short. */
  unitDisplay?: 'short' | 'long' | 'narrow';
  /** Maximum decimals above the base unit; defaults to 1. */
  maximumFractionDigits?: number;
}

/**
 * Formats a size with localized Intl unit labels, rounding into the next unit when needed.
 * Bytes scale through petabytes, bits through terabits; non-finite values return `—`.
 * A string second argument remains shorthand for the locale.
 * @example formatBytes(1536, 'es') // '1,5 kB'
 * @example formatBytes(26_214_400, { base: 1024 }) // '25 MiB'
 */
export function formatBytes(value: number, options: string | FormatBytesOptions = {}): string {
  if (!Number.isFinite(value)) return '—';
  const {
    locale = 'en',
    base = 1000,
    unit = 'byte',
    unitDisplay = 'short',
    maximumFractionDigits = 1,
  } = typeof options === 'string' ? { locale: options } : options;
  const scale = unit === 'bit' ? 1000 : base;
  const prefixes = ['', 'kilo', 'mega', 'giga', 'tera', 'peta'];
  const last = unit === 'bit' ? 4 : 5;
  let magnitude = Math.abs(value);
  let index = 0;
  while (magnitude >= scale && index < last) {
    magnitude /= scale;
    index++;
  }
  // Intl rounding also handles decimal ties that binary toFixed can round down.
  const rounded = new Intl.NumberFormat('en', {
    maximumFractionDigits: index === 0 ? 0 : maximumFractionDigits,
    useGrouping: false,
  }).format(magnitude);
  if (Number(rounded) >= scale && index < last) {
    magnitude /= scale;
    index++;
  }
  const signed = value < 0 ? -magnitude : magnitude;
  const numberOptions = { maximumFractionDigits: index === 0 ? 0 : maximumFractionDigits };
  if ((unit === 'byte' && index === 0 && unitDisplay === 'short') || (scale === 1024 && index > 0)) {
    const symbol = ['B', 'KiB', 'MiB', 'GiB', 'TiB', 'PiB'][index];
    return `${new Intl.NumberFormat(locale, numberOptions).format(signed)} ${symbol}`;
  }
  return new Intl.NumberFormat(locale, {
    ...numberOptions,
    style: 'unit',
    unit: `${prefixes[index]}${unit}`,
    unitDisplay,
  }).format(signed);
}

/** Scripts written right to left (language subtag). */
const RTL_LANGUAGES = new Set(['ar', 'arc', 'ckb', 'dv', 'fa', 'he', 'iw', 'ks', 'ku', 'ps', 'sd', 'ug', 'ur', 'yi']);

/** `rtl` for Arabic, Hebrew, Persian, Urdu… (by language subtag or Intl text info), else `ltr`. */
export function localeDirection(locale: string): 'ltr' | 'rtl' {
  try {
    const loc = new Intl.Locale(locale) as Intl.Locale & {
      getTextInfo?: () => { direction?: string };
      textInfo?: { direction?: string };
    };
    const info = loc.getTextInfo?.() ?? loc.textInfo;
    if (info?.direction === 'rtl' || info?.direction === 'ltr') return info.direction;
    return RTL_LANGUAGES.has(loc.language) ? 'rtl' : 'ltr';
  } catch {
    return RTL_LANGUAGES.has(locale.split(/[-_]/)[0]?.toLowerCase() ?? '') ? 'rtl' : 'ltr';
  }
}

/** Index of the brace closing the one at `open` (nested braces allowed). */
function matchBrace(text: string, open: number): number {
  let depth = 0;
  for (let i = open; i < text.length; i++) {
    if (text[i] === '{') depth++;
    else if (text[i] === '}' && --depth === 0) return i;
  }
  return -1;
}

/** `one {# item} other {# items}` → `{ one: '# item', other: '# items' }`. */
function parseBranches(body: string): Record<string, string> {
  const branches: Record<string, string> = {};
  let i = 0;
  while (i < body.length) {
    const open = body.indexOf('{', i);
    if (open < 0) break;
    const name = body.slice(i, open).trim();
    const close = matchBrace(body, open);
    if (close < 0) break;
    branches[name] = body.slice(open + 1, close);
    i = close + 1;
  }
  return branches;
}

/** Fills `{name}` placeholders and `{count, plural, one {…} other {…}}` selectors. */
export function interpolate(template: string, vars: MessageVars | undefined, locale: string): string {
  if (!vars || !template.includes('{')) return template;
  let out = '';
  let i = 0;
  while (i < template.length) {
    const open = template.indexOf('{', i);
    if (open < 0) {
      out += template.slice(i);
      break;
    }
    out += template.slice(i, open);
    const close = matchBrace(template, open);
    if (close < 0) {
      out += template.slice(open);
      break;
    }
    const inner = template.slice(open + 1, close);
    const plural = /^\s*(\w+)\s*,\s*plural\s*,(.*)$/s.exec(inner);
    if (plural) {
      const name = plural[1] ?? '';
      const n = Number(vars[name] ?? 0);
      const branches = parseBranches(plural[2] ?? '');
      const rule = new Intl.PluralRules(locale).select(n);
      const branch = branches[`=${n}`] ?? branches[rule] ?? branches.other ?? '';
      out += interpolate(branch.replaceAll('#', new Intl.NumberFormat(locale).format(n)), vars, locale);
    } else {
      const value = vars[inner.trim()];
      out += value === undefined ? `{${inner}}` : String(value);
    }
    i = close + 1;
  }
  return out;
}

export type DateValue = Date | number | string;
const toDate = (value: DateValue) => (value instanceof Date ? value : new Date(value));

const RELATIVE_UNITS: [Intl.RelativeTimeFormatUnit, number][] = [
  ['year', 365 * 24 * 3600],
  ['month', 30 * 24 * 3600],
  ['week', 7 * 24 * 3600],
  ['day', 24 * 3600],
  ['hour', 3600],
  ['minute', 60],
  ['second', 1],
];

/** The translator and Intl formatters for one locale. */
export interface I18nFormatters {
  /** Translates a built-in key, filling placeholders. */
  t: (key: MessageKey, vars?: MessageVars) => string;
  formatNumber: (value: number, options?: Intl.NumberFormatOptions) => string;
  formatBytes: (value: number, options?: FormatBytesOptions) => string;
  formatCurrency: (value: number, currency: string, options?: Intl.NumberFormatOptions) => string;
  formatDate: (value: DateValue, options?: Intl.DateTimeFormatOptions) => string;
  /**
   * Relative time. With a unit, formats `value` in it ("in 3 days"); with a date, picks the
   * largest fitting unit against `now` ("5 minutes ago").
   */
  formatRelativeTime: {
    (value: number, unit: Intl.RelativeTimeFormatUnit, options?: Intl.RelativeTimeFormatOptions): string;
    (value: Date, now?: Date | number, options?: Intl.RelativeTimeFormatOptions): string;
  };
  formatList: (items: readonly string[], options?: Intl.ListFormatOptions) => string;
}

export function createFormatters(locale: string, messages: Messages, timeZone = 'system'): I18nFormatters {
  const dateCache = new Map<string, Intl.DateTimeFormat>();
  const formatDate = (value: DateValue, options: Intl.DateTimeFormatOptions = { dateStyle: 'medium' }) => {
    const zone = options.timeZone ?? timeZone;
    const resolved = { ...options, timeZone: zone === 'system' ? undefined : zone };
    const key = JSON.stringify(resolved);
    let formatter = dateCache.get(key);
    if (!formatter) {
      formatter = new Intl.DateTimeFormat(locale, resolved);
      dateCache.set(key, formatter);
    }
    return formatter.format(toDate(value));
  };
  function formatRelativeTime(
    value: number,
    unit: Intl.RelativeTimeFormatUnit,
    options?: Intl.RelativeTimeFormatOptions,
  ): string;
  function formatRelativeTime(value: Date, now?: Date | number, options?: Intl.RelativeTimeFormatOptions): string;
  function formatRelativeTime(
    value: number | Date,
    unitOrNow?: Intl.RelativeTimeFormatUnit | Date | number,
    options: Intl.RelativeTimeFormatOptions = { numeric: 'auto' },
  ): string {
    const rtf = new Intl.RelativeTimeFormat(locale, options);
    if (typeof value === 'number' && typeof unitOrNow === 'string') return rtf.format(value, unitOrNow);
    const now =
      unitOrNow instanceof Date ? unitOrNow.getTime() : typeof unitOrNow === 'number' ? unitOrNow : Date.now();
    const seconds = Math.round((toDate(value).getTime() - now) / 1000);
    const [unit, size] = RELATIVE_UNITS.find(([, s]) => Math.abs(seconds) >= s) ?? ['second', 1];
    return rtf.format(Math.round(seconds / size), unit);
  }
  return {
    t: (key, vars) => interpolate(messages[key] ?? key, vars, locale),
    formatNumber: (value, options) => new Intl.NumberFormat(locale, options).format(value),
    formatBytes: (value, options) => formatBytes(value, { locale, ...options }),
    formatCurrency: (value, currency, options) =>
      new Intl.NumberFormat(locale, { style: 'currency', currency, ...options }).format(value),
    formatDate,
    formatRelativeTime,
    formatList: (items, options = { style: 'long', type: 'conjunction' }) =>
      new Intl.ListFormat(locale, options).format(items),
  };
}

import { en, type Messages } from './en';
import { es } from './es';

/** Built-in catalogs, by language subtag. */
export const catalogs = { en, es } satisfies Record<string, Messages>;
export type CatalogLocale = keyof typeof catalogs;

export const motionEn = {
  'motion.reduce': 'Reduce motion',
  'motion.description': 'Turn off animations and transitions in this app, even if your device allows them.',
  'motion.preview': 'Motion preview',
  'motion.reduced': 'Reduced motion',
  'motion.system': 'System motion preference',
};

export const motionEs: Record<keyof typeof motionEn, string> = {
  'motion.reduce': 'Reducir movimiento',
  'motion.description':
    'Desactiva las animaciones y transiciones en esta aplicación, aunque tu dispositivo las permita.',
  'motion.preview': 'Vista previa del movimiento',
  'motion.reduced': 'Movimiento reducido',
  'motion.system': 'Preferencia de movimiento del sistema',
};

/** Wall-clock fields. Months are 1–12; values remain Date instants at public boundaries. */
export interface ZonedParts {
  year: number;
  month: number;
  day: number;
  hour: number;
  minute: number;
  second?: number;
  millisecond?: number;
}

const cache = new Map<string, Intl.DateTimeFormat>();
function formatter(locale: string, timeZone: string | undefined, options: Intl.DateTimeFormatOptions) {
  const key = JSON.stringify([locale, timeZone, options]);
  let fmt = cache.get(key);
  if (!fmt) {
    fmt = new Intl.DateTimeFormat(locale, { ...options, timeZone });
    cache.set(key, fmt);
  }
  return fmt;
}

/** `system` is a kit sentinel, never an Intl timeZone. */
function intlZone(timeZone: string) {
  return timeZone === 'system' ? undefined : timeZone;
}

export function isValidTimeZone(name: string): boolean {
  if (name === 'system') return true;
  try {
    formatter('en-US', name, {});
    return true;
  } catch {
    return false;
  }
}

/** Read an instant on the wall clock of a zone (default: the runtime's local clock). */
export function zonedParts(date: Date, timeZone = 'system'): Required<ZonedParts> {
  if (timeZone === 'system') {
    return {
      year: date.getFullYear(),
      month: date.getMonth() + 1,
      day: date.getDate(),
      hour: date.getHours(),
      minute: date.getMinutes(),
      second: date.getSeconds(),
      millisecond: date.getMilliseconds(),
    };
  }
  const values: Record<string, number> = {};
  for (const part of formatter('en-US-u-ca-iso8601-nu-latn', timeZone, {
    year: 'numeric',
    month: 'numeric',
    day: 'numeric',
    hour: 'numeric',
    minute: 'numeric',
    second: 'numeric',
    hourCycle: 'h23',
  }).formatToParts(date)) {
    if (part.type !== 'literal') values[part.type] = Number(part.value);
  }
  return {
    year: values.year!,
    month: values.month!,
    day: values.day!,
    hour: values.hour!,
    minute: values.minute!,
    second: values.second!,
    millisecond: date.getUTCMilliseconds(),
  };
}

function wallEpoch(parts: ZonedParts): number {
  const date = new Date(0);
  date.setUTCFullYear(parts.year, parts.month - 1, parts.day);
  date.setUTCHours(parts.hour, parts.minute, parts.second ?? 0, parts.millisecond ?? 0);
  return date.getTime();
}

/**
 * Convert wall time to an instant. Compatible chooses the earlier overlap and moves a gap
 * forward by its duration. Reject returns null for either. Invalid calendar fields return null.
 */
export function fromZonedParts(
  parts: ZonedParts,
  timeZone = 'system',
  disambiguation: 'compatible' | 'reject' = 'compatible',
): Date | null {
  const wall = wallEpoch(parts);
  if (!Number.isFinite(wall)) return null;
  const normalized = zonedParts(new Date(wall), 'UTC');
  if (Object.entries(parts).some(([key, value]) => normalized[key as keyof ZonedParts] !== value)) return null;
  // Sampling both sides of a transition finds both possible offsets, including half-hour DST.
  const offsets = new Set<number>();
  for (const delta of [-36, 0, 36]) {
    const instant = wall + delta * 3_600_000;
    offsets.add(wallEpoch(zonedParts(new Date(instant), timeZone)) - instant);
  }
  const candidates = [...offsets].map((offset) => wall - offset).sort((a, b) => a - b);
  const matches = candidates.filter((ms) => wallEpoch(zonedParts(new Date(ms), timeZone)) === wall);
  if (disambiguation === 'reject' && matches.length !== 1) return null;
  const result = matches[0] ?? candidates[candidates.length - 1];
  return result === undefined ? null : new Date(result);
}

/** Short zone name when ICU has one, otherwise its GMT offset. UTC always reads "UTC". */
export function formatTimeZoneLabel(timeZone: string, date: Date = new Date(), locale = 'en-US'): string {
  if (timeZone === 'UTC') return 'UTC';
  const zone = intlZone(timeZone);
  return (
    formatter(locale, zone, { timeZoneName: 'short' })
      .formatToParts(date)
      .find((part) => part.type === 'timeZoneName')?.value ??
    formatter(locale, zone, { timeZoneName: 'shortOffset' })
      .formatToParts(date)
      .find((part) => part.type === 'timeZoneName')?.value ??
    'GMT'
  );
}

/**
 * Component documentation contract. Every component folder exports a `*.doc.ts`
 * with this shape; the registry build and the docs site read it.
 */
export interface ComponentDoc {
  /** Public component name, e.g. "Button". */
  name: string;
  /** Inventory group, e.g. "Actions", "Forms", "Overlays". */
  group: 'Actions' | 'Forms' | 'Overlays' | 'Navigation' | 'Display' | 'Feedback' | 'Layout' | 'Theme';
  /** Lifecycle badge. */
  status: 'stable' | 'beta' | 'experimental';
  description: string;
  /** Headless primitive it is built on, if any (e.g. "@base-ui/react/dialog"). */
  primitive?: string;
  /** WAI-ARIA pattern the a11y contract test checks. */
  pattern?: string;
  /** Keyboard contract: key → behaviour. Each row is covered by a test. */
  keyboard?: Array<[key: string, behaviour: string]>;
  /** JSX skeleton of the public compound parts. */
  anatomy?: string;
  /** State attribute, styled part and its meaning. */
  dataAttributes?: Array<[attribute: string, part: string, meaning: string]>;
  /** Tokens the component reads (for the theming docs). */
  tokens?: string[];
}
